'use client'

import { useState, useRef, useEffect, useLayoutEffect, useId, cloneElement, isValidElement, ReactNode } from 'react'
import { motion, AnimatePresence, useReducedMotion } from 'motion/react'
import { Surface } from '@/components/stepwise/primitives/surface'
import { cn } from '@/lib/utils/cn'

export type PopoverSide = 'bottom' | 'top'
export type PopoverAlign = 'start' | 'center' | 'end'

export interface PopoverProps {
  trigger: ReactNode
  children: ReactNode
  side?: PopoverSide
  align?: PopoverAlign
  /** Controlled open state — omit for uncontrolled. */
  open?: boolean
  onOpenChange?: (open: boolean) => void
  className?: string
  /** Extra classes on the floating panel. */
  contentClassName?: string
  /**
   * Accessible name for the floating panel (it's `role="dialog"`). Falls
   * back to the trigger's own `aria-label` or plain-string text when omitted.
   */
  'aria-label'?: string
}

// Motion tokens (transitions-dev): dropdown open/close is asymmetric — the
// open invites (250ms, --duration-fast), the close gets out of the way
// faster (150ms, --duration-quick). Scale is asymmetric too: 0.97
// (--scale-medium) on the way in, a much subtler 0.99 (--scale-tiny) on the
// way out. Distance is --distance-base (8px), carried by the enter phase
// only — the exit drops it to a quiet fade instead of flinging the panel
// back toward the trigger.
const EASE = [0.22, 1, 0.36, 1] as const
const OPEN_DUR = 0.25
const CLOSE_DUR = 0.15
const OPEN_SCALE = 0.97
const CLOSE_SCALE = 0.99
const DISTANCE = 8
const EDGE_MARGIN = 8

const alignX: Record<PopoverAlign, string> = {
  start: 'left-0',
  center: 'left-1/2 -translate-x-1/2',
  end: 'right-0',
}

const panelVariants = (side: PopoverSide, reduce: boolean) => ({
  hidden: {
    opacity: 0,
    scale: reduce ? 1 : OPEN_SCALE,
    y: reduce ? 0 : side === 'top' ? DISTANCE : -DISTANCE,
    filter: reduce ? 'blur(0px)' : 'blur(2px)',
  },
  visible: {
    opacity: 1,
    scale: 1,
    y: 0,
    filter: 'blur(0px)',
    transition: { duration: reduce ? 0.1 : OPEN_DUR, ease: EASE },
  },
  exit: {
    opacity: 0,
    scale: reduce ? 1 : CLOSE_SCALE,
    filter: 'blur(0px)',
    transition: { duration: reduce ? 0.1 : CLOSE_DUR, ease: EASE },
  },
})

export function Popover({
  trigger,
  children,
  side = 'bottom',
  align = 'center',
  open: controlledOpen,
  onOpenChange,
  className,
  contentClassName,
  'aria-label': ariaLabel,
}: PopoverProps) {
  const [internal, setInternal] = useState(false)
  const open = controlledOpen ?? internal
  const reduce = useReducedMotion()
  const rootRef = useRef<HTMLDivElement>(null)
  const panelRef = useRef<HTMLDivElement>(null)
  const triggerRef = useRef<HTMLElement | null>(null)
  const contentId = useId()

  // Preferred placement comes from props; resolved placement is what
  // actually fits once the panel's real size is known post-mount.
  const [resolvedSide, setResolvedSide] = useState(side)
  const [offsetX, setOffsetX] = useState(0)

  const setOpen = (v: boolean) => {
    if (controlledOpen === undefined) setInternal(v)
    onOpenChange?.(v)
  }

  useEffect(() => {
    if (!open) return
    const onDown = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false)
    }
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && setOpen(false)
    document.addEventListener('mousedown', onDown)
    document.addEventListener('keydown', onKey)
    return () => {
      document.removeEventListener('mousedown', onDown)
      document.removeEventListener('keydown', onKey)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open])

  // Move focus into the panel on open (there's usually something worth
  // landing on — a form field, an action) and always hand it back to the
  // trigger on close, however the panel closed (Escape, outside click, or
  // toggling the trigger again).
  useEffect(() => {
    if (!open) {
      triggerRef.current?.focus?.()
      return
    }
    const panel = panelRef.current
    const focusable = panel?.querySelector<HTMLElement>(
      'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
    )
    focusable?.focus()
  }, [open])

  // Flip vertically and clamp horizontally when the preferred placement
  // would push the panel off-screen. Runs in useLayoutEffect so any
  // correction lands before the browser paints — no visible jump.
  useLayoutEffect(() => {
    if (!open) { setResolvedSide(side); setOffsetX(0); return }
    const trigger = rootRef.current
    const panel = panelRef.current
    if (!trigger || !panel) return
    const tRect = trigger.getBoundingClientRect()
    const pRect = panel.getBoundingClientRect()

    let nextSide = side
    if (side === 'bottom' && pRect.bottom > window.innerHeight - EDGE_MARGIN) {
      if (tRect.top - pRect.height - EDGE_MARGIN >= 0) nextSide = 'top'
    } else if (side === 'top' && pRect.top < EDGE_MARGIN) {
      if (tRect.bottom + pRect.height + EDGE_MARGIN <= window.innerHeight) nextSide = 'bottom'
    }
    setResolvedSide(nextSide)

    let dx = 0
    if (pRect.left < EDGE_MARGIN) dx = EDGE_MARGIN - pRect.left
    else if (pRect.right > window.innerWidth - EDGE_MARGIN) dx = (window.innerWidth - EDGE_MARGIN) - pRect.right
    setOffsetX(dx)
  }, [open, side, align])

  const originY = resolvedSide === 'top' ? 'bottom' : 'top'
  const originX = align === 'end' ? 'right' : align === 'start' ? 'left' : 'center'

  // Cloning the trigger (rather than wrapping it in an extra clickable div)
  // lets the ARIA disclosure attributes and the focus-return ref land on the
  // real interactive element itself — a <div onClick> around it would carry
  // aria-expanded/aria-haspopup on a node that's never actually focusable,
  // so assistive tech would never see them.
  const isElementTrigger = isValidElement<Record<string, unknown>>(trigger)

  if (process.env.NODE_ENV !== 'production' && !isElementTrigger) {
    console.warn('[Stepwise Popover] `trigger` should be a single element (e.g. a Button) — a non-element trigger falls back to a plain, non-keyboard-accessible click target.')
  }

  const triggerElement = isElementTrigger
    ? cloneElement(trigger, {
        ref: triggerRef,
        'aria-haspopup': 'dialog',
        'aria-expanded': open,
        'aria-controls': contentId,
        onClick: (e: React.MouseEvent) => {
          ;(trigger.props as { onClick?: (e: React.MouseEvent) => void }).onClick?.(e)
          setOpen(!open)
        },
      })
    : trigger

  const triggerProps = isElementTrigger ? (trigger.props as Record<string, unknown>) : undefined
  const triggerOwnLabel = typeof triggerProps?.['aria-label'] === 'string' ? (triggerProps['aria-label'] as string) : undefined
  const triggerText = typeof triggerProps?.children === 'string' ? (triggerProps.children as string) : undefined
  const resolvedLabel = ariaLabel ?? triggerOwnLabel ?? triggerText

  return (
    <div ref={rootRef} className={cn('relative inline-block', className)}>
      {isElementTrigger ? triggerElement : <div onClick={() => setOpen(!open)}>{trigger}</div>}

      <AnimatePresence>
        {open && (
          <motion.div
            className={cn(
              'absolute z-50',
              resolvedSide === 'top' ? 'bottom-[calc(100%+8px)]' : 'top-[calc(100%+8px)]',
              alignX[align],
            )}
            style={{ transformOrigin: `${originY} ${originX}`, marginLeft: offsetX }}
            variants={panelVariants(resolvedSide, !!reduce)}
            initial="hidden"
            animate="visible"
            exit="exit"
          >
            <Surface
              ref={panelRef}
              id={contentId}
              radius={16}
              lisse={{ middleBorder: { width: 1, opacity: 1, color: 'var(--ui-border)' } }}
              className={cn(
                'bg-white p-3 shadow-[0_4px_16px_-4px_rgba(0,0,0,0.12),0_2px_6px_-2px_rgba(0,0,0,0.06)] dark:bg-zinc-900 dark:shadow-[0_10px_30px_-6px_rgba(0,0,0,0.6)]',
                contentClassName,
              )}
              role="dialog"
              aria-label={resolvedLabel}
              tabIndex={-1}
            >
              {children}
            </Surface>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}

'use client'

import { forwardRef } from 'react'
import { SmoothCorners, type SmoothCornersOwnProps, type SmoothCornerOptions } from '@lisse/react'
import { cn } from '@/lib/utils/cn'

interface SurfaceProps extends React.HTMLAttributes<HTMLDivElement> {
  radius?: number
  smoothing?: number
  /** Override for per-corner config — takes precedence over radius/smoothing. */
  corners?: SmoothCornerOptions
  // `className` isn't part of SmoothCornersOwnProps — it comes from the
  // polymorphic element props (ComponentPropsWithoutRef<E>) instead — but
  // it's a legitimate, commonly-needed passthrough (e.g. forcing `h-full`
  // through the SmoothCorners wrapper), so it's added back explicitly here.
  lisse?: Omit<SmoothCornersOwnProps, 'corners'> & { className?: string }
}

export const Surface = forwardRef<HTMLDivElement, SurfaceProps>(({
  radius = 12,
  smoothing = 0.6,
  corners,
  className,
  children,
  lisse,
  ...rest
}, ref) => {
  return (
    <SmoothCorners corners={corners ?? { radius, smoothing }} {...lisse}>
      <div ref={ref} className={cn(className)} {...rest}>
        {children}
      </div>
    </SmoothCorners>
  )
})

Surface.displayName = 'Surface'

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
